/bin/bash -lc "python3 - <<'PY'
import sqlite3,json,re
c=sqlite3.connect('file:database.sqlite?mode=ro',uri=True)
print('ABSENT_DOCUMENT_WITH_VERIFIED_DISPOSITION',c.execute(\"SELECT x.cr,p.pack_number,a.code,m.label FROM cr_in_pack x JOIN cr_pack p ON p.id=x.pack_id LEFT JOIN document d ON d.id=x.cr JOIN disposition a ON a.target=x.cr JOIN resolution r ON r.id=a.resolution_id JOIN meeting m ON m.id=r.meeting_id WHERE d.id IS NULL AND a.evidence_status='source_verified' AND a.scope='whole_target' AND m.wg='RAN3'\").fetchall())
for x in json.load(open('packet.json'))['items']:
 if x['question'].startswith('Trace '):
  number,cr,spec=re.search(r'(R3-\\d+) \\(CR (\\d+) to TS ([\\d.]+)\\)',x['question']).groups()
  rows=c.execute(\"SELECT s.spec,s.release,s.clause FROM document d JOIN cr_modifies_section x ON x.cr=d.id JOIN section s ON s.id=x.section_id WHERE d.number=? AND s.spec<>?\",(number,spec)).fetchall()
  if rows: print('TRACE_OTHER_SPECS',x['id'],rows)
PY"

